
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const events=()=>{try{return JSON.parse(localStorage.getItem('ge-demo-events')||'[]')}catch{return []}};
function track(event,detail=''){try{let a=events();a.push({concept:document.body.dataset.concept,event,detail,time:new Date().toISOString()});localStorage.setItem('ge-demo-events',JSON.stringify(a.slice(-300)))}catch{}}
track('view');
const dlg=$('#brief');let briefText='';
$$('[data-brief]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.focus)$('#focus').value=b.dataset.focus;$('#briefResult').classList.add('hide');dlg.showModal();track('cta_open',b.textContent.trim())}));
$('.close')?.addEventListener('click',()=>dlg.close());
dlg?.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
$('#briefForm')?.addEventListener('submit',e=>{e.preventDefault();briefText='Growth Element conversation brief\nFocus: '+$('#focus').value+'\nChallenge: '+$('#challenge').value.trim();$('#briefText').textContent=briefText;$('#briefText').style.whiteSpace='pre-wrap';$('#briefResult').classList.remove('hide');track('brief_created',$('#focus').value)});
$('#copyBrief')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(briefText);$('#copyStatus').textContent='Copied. No information has been sent.'}catch{$('#copyStatus').textContent='Copy is unavailable in this browser. Select and copy the brief above.'}});
function calculate(){let h=+$('#hours').value,s=+$('#share').value,r=+$('#rate').value;$('#hoursVal').textContent=h+' h';$('#shareVal').textContent=s+'%';$('#rateVal').textContent='$'+r;$('#saved').textContent=+(h*s/100).toFixed(1)+' h';$('#value').textContent='$'+Math.round(h*s/100*52/12*r).toLocaleString('en-US')}
if($('#hours')){$$('.calc input').forEach(x=>{x.addEventListener('input',calculate);x.addEventListener('change',()=>track('calculator_change',x.id))});calculate()}
const routes={story:{title:'Start with the story.',text:'Clarify the message, then build the deck, film or content that makes it useful.',focus:'Brand & Content'},store:{title:'Start with the buying experience.',text:'Walk the store as a customer. Find friction, review the baseline, and prioritize the first improvement.',focus:'Ecommerce Growth'},time:{title:'Start with one repeating workflow.',text:'Map the handoffs, check what can be automated, and keep human review where it matters.',focus:'AI'}};
$$('[data-route]').forEach(b=>b.addEventListener('click',()=>{let r=routes[b.dataset.route],parent=b.closest('[data-router]');parent.querySelectorAll('[data-route]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let result=parent.querySelector('[data-reply]');result.innerHTML='<strong>'+r.title+'</strong><p>'+r.text+'</p><button class="textlink" style="background:transparent;border:0;border-bottom:1px solid var(--line);cursor:pointer;padding:0 0 4px" data-selected>Talk through this challenge ↗</button>';result.querySelector('button').onclick=()=>{$('#focus').value=r.focus;$('#briefResult').classList.add('hide');dlg.showModal();track('cta_open',r.focus)};track('path_selected',r.focus)}));
$('#pause')?.addEventListener('click',()=>{const s=$('.motionstage'),paused=s.classList.toggle('paused');$('#pause').textContent=paused?'Play motion':'Pause motion';$('#pause').setAttribute('aria-pressed',String(paused))});
$('#exportEvents')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(events(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='growth-element-local-test-events.json';a.click();URL.revokeObjectURL(a.href);$('#eventStatus').textContent='Exported this browser’s preview interactions. No traffic or lead analytics are connected.'});
